import bpy
info=[]
for o in bpy.data.objects:
    if o.name.startswith("Lantern_") and "Cap" not in o.name and "Cord" not in o.name:
        mats=[m.name if m else None for m in o.data.materials] if hasattr(o.data,'materials') else []
        info.append({"name":o.name,"type":o.type,"loc":tuple(round(v,3) for v in o.location),"dim":tuple(round(v,3) for v in o.dimensions),"hide":(o.hide_render,o.hide_viewport),"mats":mats,"verts":len(o.data.vertices) if o.type=='MESH' else -1})
sm=bpy.data.objects.get("Smile")
smi={"loc":tuple(round(v,3) for v in sm.location),"rot":tuple(round(v,3) for v in sm.rotation_euler),"scale":tuple(round(v,3) for v in sm.scale)} if sm else None
result={"globes":info,"smile":smi}

import bpy
# remove old lantern assembly
for o in [o for o in bpy.data.objects if "Lantern" in o.name]:
    bpy.data.objects.remove(o, do_unlink=True)
M={m.name:m for m in bpy.data.materials}
def prim_cyl(name, loc, r, depth, material=None, verts=16):
    bpy.ops.mesh.primitive_cylinder_add(radius=r, depth=depth, vertices=verts, location=loc)
    o=bpy.context.active_object; o.name=name
    if material: o.data.materials.append(material)
    return o
def prim_sphere(name, loc, r, material=None, sx=1, sy=1, sz=1):
    bpy.ops.mesh.primitive_uv_sphere_add(radius=r, segments=18, ring_count=12, location=loc)
    o=bpy.context.active_object; o.name=name; o.scale=(sx,sy,sz)
    bpy.ops.object.transform_apply(scale=True)
    if material: o.data.materials.append(material)
    return o
for x in [-1.15, 1.15]:
    prim_sphere(f"PaperLantern_{x}", (x,0.95,2.3), 0.2, M.get("Lantern"), 1, 1, 1.25)
    prim_cyl(f"PaperLanternCapT_{x}", (x,0.95,2.57), 0.07, 0.05, M.get("Black"))
    prim_cyl(f"PaperLanternCapB_{x}", (x,0.95,2.02), 0.07, 0.05, M.get("Black"))
    prim_cyl(f"PaperLanternCord_{x}", (x,0.95,2.66), 0.012, 0.16, M.get("Black"))
# replace smile torus with open happy mouth
sm=bpy.data.objects.get("Smile")
if sm: bpy.data.objects.remove(sm, do_unlink=True)
prim_sphere("Mouth", (0,-0.60,1.68), 0.07, M.get("Black"), 1.1, 0.55, 1.3)
result={"ok":True,"n":len(bpy.context.scene.objects)}

